{
  "errors": [
    {
      "error_type": "格式错误",
      "spans": [
        {
          "text": "帝科股份(3008-42)"
        }
      ],
      "reason": "股票代码应为六位数字，此处写成“3008-42”，不符合证券代码格式。"
    },
    {
      "error_type": "数值缺失",
      "spans": [
        {
          "text": "公司营收稳定增长，2024年总营收亿元，归母净利润接近3.6亿元，近三年毛利率维持在10%左右。"
        }
      ],
      "reason": "“2024年总营收”后直接接“亿元”，缺少应报告的具体数值。"
    },
    {
      "error_type": "计算错误",
      "spans": [
        {
          "text": "毛利率11.14%、9.38%，YOY+2.3pct、-1.8pct；"
        }
      ],
      "reason": "23年毛利率11.14%下降1.8pct应为9.34%，与所列24年毛利率9.38%不一致。"
    },
    {
      "error_type": "术语误用",
      "spans": [
        {
          "text": "债权费用率在期间费用率中占比最高，公司23、24年债权费用率分别是3.2%、3.1%。"
        }
      ],
      "reason": "“债权费用率”不是规范财务指标，期间费用率中对应项目通常表述为财务费用率。"
    }
  ]
}
